# my free storage on Google Drive was getting pretty full, mostly due to the MMS messages from my device backup

# I know that there are already versions of this out there, but I wanted to write my own
# this script will extract the images from the XML file generated by the Android app "SMS Backup and Restore," and
# save each one with the appropriate extension to a contact-specific subfolder within the specified output directory

# this way, the images can be bulk-deleted from the device and removed from the Google Drive device backup

import xml.etree.ElementTree as ET
import os
from datetime import datetime
import base64

xml_file = os.path.join('C:\\', 'path', 'to_your', 'your_backup.xml')
base_output_dir = os.path.join('C:\\', 'path', 'to_your', 'base', 'output_directory')

def get_mms_messages(xml):
    tree = ET.parse(xml)
    root = tree.getroot()

    mms_messages = [m for m in root.findall('mms')]
    # has_images = [m for m in mms_messages if m.get('ct_t').startswith('image')]
    print(f'Found {len(mms_messages)} MMS messages')

    return mms_messages


def process_image(mms):
    timestamp = int(mms.get('date'))/1000 # XML timestamp uses milliseconds
    mms_datetime = datetime.fromtimestamp(timestamp).strftime('%Y%m%d-%H%M%S')
    contact_number = mms.get('address') if mms.get('address') else 'Unknown Sender'
    contact_name = mms.get('contact_name') if mms.get('contact_name') else contact_number
    output_dir = os.path.join(base_output_dir, contact_name)

    direction = 'received' if mms.get('msg_box') == '1' else 'sent'

    mms_parts = mms.findall('parts/part')
    print('Found {} parts in MMS timestamp {}'.format(len(mms_parts), mms_datetime))

    for part in mms_parts:
        if part.get('ct').startswith('image'):
            ext = part.get('ct').split('/')[-1]
            print(f'{direction} image with extension {ext} being processed')

            filename = f'{contact_number}_{mms_datetime}_{direction}.{ext}'
            print(f'Attempting to create {os.path.join(output_dir, filename)}')

            if not os.path.exists(output_dir):
                os.makedirs(output_dir)
                print(f'Output directory {output_dir} created')

            count = 1
            while os.path.exists(os.path.join(output_dir, filename)):
                filename = f'{contact_number}_{mms_datetime}_{direction}_{count}.{ext}'
                count += 1

            image_base64 = base64.b64decode(part.get('data'))
            with open(os.path.join(output_dir, filename), 'wb') as f:
                f.write(image_base64)

            print(f'Successfully created {os.path.join(output_dir, filename)}')

def main():
    mms = get_mms_messages(xml_file)
    print(f'Found {len(mms)} MMS messages in {xml_file}')

    count=1
    for message in mms:
        print(f'Processing message {count}')
        process_image(message)
        print(f'Finished processing message {count}')
        count += 1

if __name__ == '__main__':
    main()
